-- 副将名将池表（管理后台「副将管理」模块，游戏端启动时拉取覆盖内置 VICE_DEFS）
create table if not exists admin_vices (
  id bigint primary key,
  v_id text,
  name text not null,
  title text,
  job text default '战士',
  gender text default '男',
  avatar text,
  quality int default 18,
  wuXing int default 9,
  zhongCheng int default 90,
  life int default 2800,
  story text,
  base_hp int default 100,
  base_mp int default 100,
  base_atk int default 100,
  base_def int default 100,
  crit double precision default 0.05,
  dodge double precision default 0.05,
  lvl int default 3,
  enhance int default 0,
  sort int default 0,
  enabled boolean default true,
  created_at timestamptz default now()
);
-- 种子：83名副将（对齐腾讯文档「武将头像」分享包 + 截图1名将；头像取游戏 static/image/upload 资源）
on conflict (id) do update set name=excluded.name,title=excluded.title,job=excluded.job,gender=excluded.gender,avatar=excluded.avatar,story=excluded.story,enabled=true;
